-- ----------------------------
-- Table structure for armor
-- ----------------------------
DROP TABLE IF EXISTS `armor`;
CREATE TABLE `armor`  (
  `item_id` int(5) NOT NULL AUTO_INCREMENT,
  `name` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'NULL',
  `classname` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `name_id` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `type` varchar(15) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `material` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `weight` int(7) UNSIGNED NOT NULL DEFAULT 0,
  `invgfx` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `grdgfx` int(5) UNSIGNED NOT NULL DEFAULT 0,
  `itemdesc_id` int(10) NOT NULL DEFAULT 0,
  `ac` int(3) NOT NULL DEFAULT 0,
  `safenchant` int(2) NOT NULL DEFAULT 0,
  `use_royal` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_knight` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_mage` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_elf` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_darkelf` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_dragonknight` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_illusionist` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `use_warrior` int(2) UNSIGNED NOT NULL DEFAULT 1,
  `add_str` int(2) NOT NULL DEFAULT 0,
  `add_con` int(2) NOT NULL DEFAULT 0,
  `add_dex` int(2) NOT NULL DEFAULT 0,
  `add_int` int(2) NOT NULL DEFAULT 0,
  `add_wis` int(2) NOT NULL DEFAULT 0,
  `add_cha` int(2) NOT NULL DEFAULT 0,
  `add_hp` int(10) NOT NULL DEFAULT 0,
  `add_mp` int(10) NOT NULL DEFAULT 0,
  `add_hpr` int(10) NOT NULL DEFAULT 0,
  `add_mpr` int(10) NOT NULL DEFAULT 0,
  `add_sp` int(10) NOT NULL DEFAULT 0,
  `min_lvl` int(4) UNSIGNED NOT NULL DEFAULT 0,
  `max_lvl` int(4) UNSIGNED NOT NULL DEFAULT 0,
  `m_def` int(2) NOT NULL DEFAULT 0,
  `haste_item` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `damage_reduction` int(10) NOT NULL DEFAULT 0,
  `weight_reduction` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `hit_modifier` int(10) NOT NULL DEFAULT 0,
  `dmg_modifier` int(10) NOT NULL DEFAULT 0,
  `bow_hit_modifier` int(10) NOT NULL DEFAULT 0,
  `bow_dmg_modifier` int(10) NOT NULL DEFAULT 0,
  `bless` int(2) UNSIGNED NOT NULL DEFAULT 1,
  `trade` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `cant_delete` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `max_use_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `defense_water` int(2) NOT NULL DEFAULT 0,
  `defense_wind` int(2) NOT NULL DEFAULT 0,
  `defense_fire` int(2) NOT NULL DEFAULT 0,
  `defense_earth` int(2) NOT NULL DEFAULT 0,
  `regist_stun` int(2) NOT NULL DEFAULT 0,
  `regist_stone` int(2) NOT NULL DEFAULT 0,
  `regist_sleep` int(2) NOT NULL DEFAULT 0,
  `regist_freeze` int(2) NOT NULL DEFAULT 0,
  `regist_sustain` int(2) NOT NULL DEFAULT 0,
  `regist_blind` int(2) NOT NULL DEFAULT 0,
  `greater` int(2) NOT NULL DEFAULT -1,
  `magic_hit_modifier` int(10) NOT NULL DEFAULT 0 COMMENT '魔法命中',
  `up_hp_potion` int(10) NOT NULL DEFAULT 0 COMMENT '藥水恢復量增加百分比',
  `uhp_number` int(10) NOT NULL DEFAULT 0 COMMENT '藥水恢復量增加固定數值',
  `is_activity` int(2) NOT NULL DEFAULT 0 COMMENT '是否為活動戒指或收費戒指',
  `exp_point` int(5) NOT NULL DEFAULT 0 COMMENT '賦予裝備經驗加倍(1.5倍)設定=50',
  `MeteLevel` int(10) NULL DEFAULT 0 COMMENT '轉生使用判斷(設置1代表1轉以上才可使用)',
  `MeteLevelMAX` int(10) NULL DEFAULT 10,
  `是否附魔超能系統` int(2) NOT NULL DEFAULT 0 COMMENT '是否可以超能附魔是(0=不可, 1=可)',
  `PVP傷害` int(2) NOT NULL DEFAULT 0 COMMENT '增加PVP傷害',
  `PVP減免` int(2) NOT NULL DEFAULT 0 COMMENT 'PVP傷害減免',
  `use_camp` int(5) NOT NULL DEFAULT 0 COMMENT '1-A.2-B.4-C.7-共用',
  `kit_type` int(2) NOT NULL DEFAULT 0,
  `機率給予爆擊` int(10) NOT NULL DEFAULT 0,
  `機率給予爆擊值` int(10) NOT NULL DEFAULT 0,
  `influence_safe` int(10) NOT NULL COMMENT '開關',
  `influence_str` int(5) NOT NULL COMMENT '使用防卷後成功+1力量+1',
  `influence_dex` int(5) NOT NULL,
  `influence_con` int(5) NOT NULL,
  `influence_int` int(5) NOT NULL,
  `influence_wis` int(5) NOT NULL,
  `influence_cha` int(5) NOT NULL,
  `influence_sp` int(5) NOT NULL,
  `influence_mr` int(5) NOT NULL,
  `influence_hp` int(5) NOT NULL COMMENT '使用防卷後成功+1增加HP',
  `influence_mp` int(5) NOT NULL COMMENT '使用防卷後成功+1增加MP',
  `influence_dmgR` int(5) NOT NULL COMMENT '使用防卷後成功+1增加傷害減免1',
  `influence_hitAndDmg` int(5) NOT NULL COMMENT '使用防卷後成功+1近距離命中/傷害+1',
  `influence_bowHitAndDmg` int(5) NOT NULL COMMENT '使用防卷後成功+1遠距離命中/傷害+1',
  `是否可存倉` int(10) NULL DEFAULT 0,
  `是否可存血盟倉` int(10) NULL DEFAULT 0,
  PRIMARY KEY (`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 822270 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

